import { useEffect, useState, useCallback } from "react";
import { getDb, ensureAnonymousLogin } from "@/lib/cloudbase";

export interface GuestbookMessage {
  id: string;
  name: string;
  message: string;
  createdAt: number;
}

export interface GuestbookFormData {
  name: string;
  message: string;
}

const COLLECTION = "guestbook";

function toMillis(value: unknown): number {
  if (!value) return Date.now();
  if (value instanceof Date) return value.getTime();
  if (
    value &&
    typeof value === "object" &&
    "toMillis" in value &&
    typeof (value as { toMillis: () => number }).toMillis === "function"
  ) {
    return (value as { toMillis: () => number }).toMillis();
  }
  return Date.now();
}

export function useGuestbook() {
  const [messages, setMessages] = useState<GuestbookMessage[]>([]);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    let timer: ReturnType<typeof setTimeout> | null = null;

    async function load() {
      try {
        await ensureAnonymousLogin();
        const db = getDb();
        const collection = db.collection(COLLECTION);
        const res = await collection
          .orderBy("createdAt", "desc")
          .limit(200)
          .get();
        if (cancelled) return;
        const parsed: GuestbookMessage[] = (res.data as Array<Record<string, unknown>>).map(
          (item) => ({
            id: (item._id as string) || "",
            name: (item.name as string) || "匿名",
            message: (item.message as string) || "",
            createdAt: toMillis(item.createdAt),
          })
        );
        setMessages(parsed);
        setLoading(false);
      } catch (err) {
        if (!cancelled) {
          setError((err as Error).message);
          setLoading(false);
        }
      }
    }

    // 首次加载并启动轮询（CloudBase Web SDK 不支持实时监听）
    load();
    timer = setInterval(load, 30000); // 30 秒刷新一次

    return () => {
      cancelled = true;
      if (timer) clearInterval(timer);
    };
  }, []);

  const submitMessage = useCallback(async (formData: GuestbookFormData) => {
    const trimmedName = formData.name.trim();
    const trimmedMessage = formData.message.trim();

    if (!trimmedName || !trimmedMessage) {
      setError("请填写昵称和留言内容");
      return false;
    }

    if (trimmedName.length > 30) {
      setError("昵称不能超过 30 个字符");
      return false;
    }

    if (trimmedMessage.length > 500) {
      setError("留言不能超过 500 个字符");
      return false;
    }

    setSubmitting(true);
    setError(null);

    try {
      await ensureAnonymousLogin();
      const db = getDb();
      const collection = db.collection(COLLECTION);
      await collection.add({
        name: trimmedName,
        message: trimmedMessage,
        createdAt: new Date(),
      });
      setSubmitting(false);
      // 立即刷新一次
      const res = await collection
        .orderBy("createdAt", "desc")
        .limit(200)
        .get();
      const parsed: GuestbookMessage[] = (res.data as Array<Record<string, unknown>>).map(
        (item) => ({
          id: (item._id as string) || "",
          name: (item.name as string) || "匿名",
          message: (item.message as string) || "",
          createdAt: toMillis(item.createdAt),
        })
      );
      setMessages(parsed);
      return true;
    } catch (err) {
      setError("提交失败：" + (err as Error).message);
      setSubmitting(false);
      return false;
    }
  }, []);

  return { messages, loading, submitting, error, submitMessage };
}
